import hashlib
import hmac
import http.cookies
import http.server
import json
import secrets
import sqlite3
import threading
import time
import urllib.parse
from datetime import datetime, timezone
from typing import Any, Dict, Optional, Tuple


class PasswordHasher:
    @staticmethod
    def hash_password(password: str) -> str:
        salt = secrets.token_hex(16)
        key = hashlib.pbkdf2_hmac(
            "sha256", password.encode("utf-8"), salt.encode("utf-8"), 100_000
        )
        return f"{salt}:{key.hex()}"

    @staticmethod
    def verify_password(stored_password: str, provided_password: str) -> bool:
        try:
            salt, stored_key = stored_password.split(":")
            new_key = hashlib.pbkdf2_hmac(
                "sha256",
                provided_password.encode("utf-8"),
                salt.encode("utf-8"),
                100_000,
            )
            return hmac.compare_digest(stored_key, new_key.hex())
        except (ValueError, AttributeError):
            return False


class SecureSessionManager:
    def __init__(self, db_path: str = ":memory:", session_ttl_seconds: int = 1800):
        self.session_ttl_seconds = session_ttl_seconds
        self._lock = threading.Lock()
        self._conn = sqlite3.connect(db_path, check_same_thread=False)
        self._init_db()

    def _init_db(self) -> None:
        with self._lock:
            with self._conn:
                self._conn.execute(
                    """
                    CREATE TABLE IF NOT EXISTS sessions (
                        token_hash TEXT PRIMARY KEY,
                        user_id TEXT NOT NULL,
                        created_at REAL NOT NULL,
                        expires_at REAL NOT NULL,
                        csrf_token TEXT NOT NULL
                    )
                    """
                )
                self._conn.execute(
                    """
                    CREATE INDEX IF NOT EXISTS idx_sessions_expires_at 
                    ON sessions(expires_at)
                    """
                )

    def _hash_token(self, token: str) -> str:
        return hashlib.sha256(token.encode("utf-8")).hexdigest()

    def create_session(self, user_id: str) -> Tuple[str, str]:
        self.cleanup_expired()
        raw_token = secrets.token_urlsafe(32)
        token_hash = self._hash_token(raw_token)
        csrf_token = secrets.token_urlsafe(32)
        now = time.time()
        expires_at = now + self.session_ttl_seconds

        with self._lock:
            with self._conn:
                self._conn.execute(
                    """
                    INSERT INTO sessions (token_hash, user_id, created_at, expires_at, csrf_token)
                    VALUES (?, ?, ?, ?, ?)
                    """,
                    (token_hash, user_id, now, expires_at, csrf_token),
                )
        return raw_token, csrf_token

    def get_session(self, raw_token: Optional[str]) -> Optional[Dict[str, Any]]:
        if not raw_token:
            return None

        token_hash = self._hash_token(raw_token)
        now = time.time()

        with self._lock:
            cursor = self._conn.cursor()
            cursor.execute(
                """
                SELECT user_id, created_at, expires_at, csrf_token 
                FROM sessions 
                WHERE token_hash = ? AND expires_at > ?
                """,
                (token_hash, now),
            )
            row = cursor.fetchone()

        if not row:
            return None

        return {
            "user_id": row[0],
            "created_at": row[1],
            "expires_at": row[2],
            "csrf_token": row[3],
        }

    def regenerate_session(self, raw_token: str) -> Optional[Tuple[str, str]]:
        session_data = self.get_session(raw_token)
        if not session_data:
            return None

        self.terminate_session(raw_token)
        return self.create_session(session_data["user_id"])

    def terminate_session(self, raw_token: Optional[str]) -> bool:
        if not raw_token:
            return False

        token_hash = self._hash_token(raw_token)
        with self._lock:
            with self._conn:
                cursor = self._conn.execute(
                    "DELETE FROM sessions WHERE token_hash = ?", (token_hash,)
                )
                return cursor.rowcount > 0

    def cleanup_expired(self) -> int:
        now = time.time()
        with self._lock:
            with self._conn:
                cursor = self._conn.execute(
                    "DELETE FROM sessions WHERE expires_at <= ?", (now,)
                )
                return cursor.rowcount


class UserRepository:
    def __init__(self):
        self._users: Dict[str, str] = {}
        self.register_user("alice", "SuperSecret123!")
        self.register_user("bob", "CorrectHorseBattery99")

    def register_user(self, username: str, password: str) -> bool:
        if username in self._users:
            return False
        self._users[username] = PasswordHasher.hash_password(password)
        return True

    def authenticate(self, username: str, password: str) -> bool:
        stored_hash = self._users.get(username)
        if not stored_hash:
            PasswordHasher.verify_password(
                "dummy:dummy", password
            )
            return False
        return PasswordHasher.verify_password(stored_hash, password)


class SecureAppHandler(http.server.BaseHTTPRequestHandler):
    session_manager = SecureSessionManager(session_ttl_seconds=900)
    user_repository = UserRepository()

    def _parse_cookies(self) -> http.cookies.SimpleCookie:
        cookie_header = self.headers.get("Cookie", "")
        cookies = http.cookies.SimpleCookie()
        if cookie_header:
            cookies.load(cookie_header)
        return cookies

    def _get_active_session(self) -> Tuple[Optional[str], Optional[Dict[str, Any]]]:
        cookies = self._parse_cookies()
        if "session_token" in cookies:
            token = cookies["session_token"].value
            session = self.session_manager.get_session(token)
            if session:
                return token, session
        return None, None

    def _parse_form_data(self) -> Dict[str, str]:
        content_length_str = self.headers.get("Content-Length", "0")
        try:
            content_length = int(content_length_str)
        except ValueError:
            content_length = 0

        post_data = self.rfile.read(content_length).decode("utf-8")
        parsed = urllib.parse.parse_qs(post_data, keep_blank_values=True)
        return {k: v[0] for k, v in parsed.items()}

    def _send_response_page(
        self,
        status_code: int,
        content: str,
        set_cookie: Optional[str] = None,
        clear_cookie: bool = False,
    ) -> None:
        self.send_response(status_code)
        self.send_header("Content-Type", "text/html; charset=utf-8")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("X-Frame-Options", "DENY")
        self.send_header(
            "Content-Security-Policy",
            "default-src 'none'; style-src 'unsafe-inline'; form-action 'self';",
        )

        if set_cookie:
            cookie_value = (
                f"session_token={set_cookie}; HttpOnly; SameSite=Strict; Path=/; Max-Age=900"
            )
            self.send_header("Set-Cookie", cookie_value)
        elif clear_cookie:
            cookie_value = (
                "session_token=deleted; HttpOnly; SameSite=Strict; Path=/; Max-Age=0"
            )
            self.send_header("Set-Cookie", cookie_value)

        body_bytes = content.encode("utf-8")
        self.send_header("Content-Length", str(len(body_bytes)))
        self.end_headers()
        self.wfile.write(body_bytes)

    def _send_redirect(
        self,
        location: str,
        set_cookie: Optional[str] = None,
        clear_cookie: bool = False,
    ) -> None:
        self.send_response(303)
        self.send_header("Location", location)
        if set_cookie:
            self.send_header(
                "Set-Cookie",
                f"session_token={set_cookie}; HttpOnly; SameSite=Strict; Path=/; Max-Age=900",
            )
        elif clear_cookie:
            self.send_header(
                "Set-Cookie",
                "session_token=deleted; HttpOnly; SameSite=Strict; Path=/; Max-Age=0",
            )
        self.send_header("Content-Length", "0")
        self.end_headers()

    def do_GET(self) -> None:
        parsed_url = urllib.parse.urlparse(self.path)
        path = parsed_url.path
        raw_token, session = self._get_active_session()

        if path == "/":
            if session:
                self._send_redirect("/dashboard")
            else:
                self._render_login_page()
        elif path == "/dashboard":
            if not session:
                self._send_redirect("/", clear_cookie=True)
            else:
                self._render_dashboard(session)
        else:
            self._send_response_page(404, "<h1>404 Not Found</h1>")

    def do_POST(self) -> None:
        parsed_url = urllib.parse.urlparse(self.path)
        path = parsed_url.path
        raw_token, session = self._get_active_session()
        params = self._parse_form_data()

        if path == "/login":
            username = params.get("username", "").strip()
            password = params.get("password", "")

            if self.user_repository.authenticate(username, password):
                if raw_token:
                    self.session_manager.terminate_session(raw_token)
                new_token, _ = self.session_manager.create_session(username)
                self._send_redirect("/dashboard", set_cookie=new_token)
            else:
                self._render_login_page(error="Invalid username or password.")

        elif path == "/logout":
            if session:
                token_csrf = params.get("csrf_token", "")
                if not hmac.compare_digest(session["csrf_token"], token_csrf):
                    self._send_response_page(403, "<h1>403 Forbidden: Invalid CSRF Token</h1>")
                    return
                self.session_manager.terminate_session(raw_token)
            self._send_redirect("/", clear_cookie=True)

        elif path == "/refresh":
            if not session or not raw_token:
                self._send_redirect("/", clear_cookie=True)
                return

            token_csrf = params.get("csrf_token", "")
            if not hmac.compare_digest(session["csrf_token"], token_csrf):
                self._send_response_page(403, "<h1>403 Forbidden: Invalid CSRF Token</h1>")
                return

            regenerated = self.session_manager.regenerate_session(raw_token)
            if regenerated:
                new_token, _ = regenerated
                self._send_redirect("/dashboard", set_cookie=new_token)
            else:
                self._send_redirect("/", clear_cookie=True)

        else:
            self._send_response_page(404, "<h1>404 Not Found</h1>")

